4.2 Statement Popularity


Code
## Popular Statements Sim at t=100
stats_pop &lt;- memory |&gt;
  filter(t == 100) |&gt;
  left_join(runs_core, by = join_by(run_id)) |&gt;
  left_join(statements_meta, by = join_by(S_id)) |&gt;
  count(run_id, S_id, Worldview_Statement, M, openmindedness, post) |&gt;
  summarize(
    popularity = sum(n),
    .by = c(S_id, Worldview_Statement, M, openmindedness, post)
  )

stats_pop_total &lt;- stats_pop |&gt;
  filter(M == 5) |&gt;
  summarize(popularity = sum(popularity), .by = c(S_id, Worldview_Statement)) |&gt;
  mutate(label = glue("{S_id} {Worldview_Statement}")) |&gt;
  arrange(desc(popularity)) |&gt;
  left_join(sttmts |&gt; select(S_id, WVS_PC1, worldview), by = join_by(S_id))
df &lt;- stats_pop_total |&gt;
  slice(1:100) |&gt;
  mutate(
    group = if_else(row_number() &lt;= 50, "Top 50", "51–100") |&gt;
      factor(levels = c("Top 50", "51–100"))
  ) |&gt;
  arrange(group, desc(popularity)) |&gt;
  mutate(
    S_id_ordered = paste(S_id, group, sep = "___"),
    S_id_ordered = fct_inorder(S_id_ordered) |&gt; fct_rev()
  )

pad &lt;- 400 # data-unit space reserved for outside labels, same in both panels
p &lt;- df |&gt;
  ggplot(aes(
    y = S_id_ordered,
    x = popularity,
    label = popularity,
    tooltip = Worldview_Statement
  )) +
  geom_col_interactive(aes(
    color = worldview,
    fill = WVS_PC1,
  )) +
  geom_text(
    aes(
      hjust = ifelse(popularity &gt; 1000, 1.1, -0.1)
    ),
    color = "black",
    size = 3
  ) +
  scale_y_discrete(labels = \(x) sub("___.*$", "", x)) +
  facet_wrap(~group, scales = "free", nrow = 1) +
  scale_x_continuous(
    breaks = c(),
    expand = expansion(mult = 0, add = c(0, pad))
  ) +
  scale_fill_continuous(palette = "RdYlBu", limits = c(-1, 1)) +
  scale_color_manual(values = c("blue", "red", "grey")) +
  labs(y = "", x = "", fill = "WVS PC1", color = "Ideology LLM coded") +
  theme_minimal() +
  theme(
    panel.grid = element_blank(),
    legend.position = "inside",
    legend.position.inside = c(0.5, 0.5),
    legend.justification.inside = c(0.5, 0.5)
  )

ranges &lt;- df |&gt;
  group_by(group) |&gt;
  summarise(xmax = max(popularity)) |&gt;
  pull(xmax)
widths &lt;- ranges + pad # matches the actual displayed range now, not an arbitrary offset

girafe(
  ggobj = p + force_panelsizes(cols = unit(widths, "null")),
  options = list(
    opts_toolbar(position = "top", fixed = TRUE)
  )
)








