6.1 All Statements


Code
statements_meta |&gt;
  select(WVS = Question_ID, S_id, Text = Worldview_Statement) |&gt;
  mutate(
    WVS = WVS |&gt;
      str_remove("Q") |&gt;
      as.numeric()
  ) |&gt;
  arrange(WVS) |&gt;
  left_join(
    stats_pop_total |&gt;
      select(S_id, Popularity = popularity),
    by = join_by(S_id)
  ) |&gt;
  replace_na(list(Popularity = 0)) |&gt;
  gt() |&gt;
  opt_interactive(
    use_sorting = TRUE,
    use_filters = TRUE,
    use_highlight = TRUE,
    use_compact_mode = TRUE,
    use_text_wrapping = TRUE,
    use_page_size_select = TRUE,
    page_size_default = 10,
    page_size_values = c(10, 25, 50, 100),
    pagination_type = c("numbers", "jump", "simple")
  ) |&gt;
  cols_width(
    WVS ~ px(60),
    S_id ~ px(90),
    Text ~ px(500),
    Popularity ~ px(100)
  )




